// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Roulette} from "../src/Roulette.sol";

contract InvMutTest is Test {
    Roulette c;
    function setUp() public { c = new Roulette(); }
    function testFuzz_property(uint256 secondTimestamp, uint256 secondBlockNumber) public {
        uint256 firstTimestamp = 1000;
        uint256 firstBlockNumber = 123;
        vm.assume(secondTimestamp > firstTimestamp && secondTimestamp < type(uint64).max);
        vm.assume(secondBlockNumber > firstBlockNumber && secondBlockNumber % 15 != 0);

        address actor = address(0x1234);
        vm.deal(actor, 20 ether);

        vm.warp(firstTimestamp);
        vm.roll(firstBlockNumber);
        vm.prank(actor);
        (bool ok1,) = address(c).call{value: 10 ether}("");
        require(ok1, "first call must succeed");

        vm.warp(secondTimestamp);
        vm.roll(secondBlockNumber);
        vm.prank(actor);
        (bool ok2,) = address(c).call{value: 10 ether}("");
        require(ok2, "second call must succeed");

        assertTrue(c.pastBlockTime() == secondTimestamp + 1);
    }
}
